import{_ as a,o,c,a5 as t}from"./chunks/framework.CXvGqWf0.js";const q=JSON.parse('{"title":"漫画 · 第 41 话 @container 进阶：组件不问屏幕，问容器状态","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.41-container-advanced.md","filePath":"comics/css/EP.41-container-advanced.md","lastUpdated":1793421609000}'),n={name:"comics/css/EP.41-container-advanced.md"};function r(i,e,d,s,l,h){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-41-话-container-进阶-组件不问屏幕-问容器状态" tabindex="-1">漫画 · 第 41 话 @container 进阶：组件不问屏幕，问容器状态 <a class="header-anchor" href="#漫画-·-第-41-话-container-进阶-组件不问屏幕-问容器状态" aria-label="Permalink to &quot;漫画 · 第 41 话 @container 进阶：组件不问屏幕，问容器状态&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/26-container-advanced">docs/css/26-container-advanced.md</a> ｜ 原画：<a href="./EP.41-container-advanced.svg">EP.41-container-advanced.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。基础容器查询用熟了，但暗色侧栏里的卡片还是白色皮肤——尺寸查询管不了「容器是什么状态」，只能给卡片传 class，业务方和组件耦合越来越深。</li><li><strong>标签君</strong>：HTML5 结构师，搬出进阶三件套——style queries 查容器的自定义属性、容器单位让组件内部随容器缩放、命名容器防嵌套串台。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>EP.22 解决了「按容器宽度换布局」，但像素酱很快撞上三堵新墙：暗色侧栏要换皮肤（查状态）、卡片内文字要随容器缩放（vw 被视口绑架）、仪表盘嵌套查询串台。标签君逐件拆解：<code>@container style(--theme: dark)</code> 直接查容器的自定义属性，无需 <code>container-type</code>；<code>cqi/cqw</code> 单位按最近尺寸容器缩放，clamp 兜底极值；<code>container: widget / inline-size</code> 命名后查询不再串台。最后 <code>@scope</code> 封装样式边界、<code>@container</code> 提供断点，组件真正「装哪美哪」。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>基础容器查询只能查尺寸。暗色侧栏要换皮肤？尺寸查询做不到，只能给卡片传 class——业务方被迫知道组件内部结构，复用成本飙升。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>style queries 查容器的 <code>--*</code> 自定义属性值，无需声明 <code>container-type</code>；容器单位 <code>cqi/cqb/cqmin/cqmax</code> 按最近尺寸容器缩放，不受视口绑架；命名容器 <code>@container widget (min-width)</code> 精确指向目标层，嵌套不串台。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：暗色侧栏自适应（<code>--theme</code> 开关零 class）、流式组件排版（<code>clamp</code> + <code>cqi</code>）、嵌套仪表盘（widget 查自己、dashboard 查外层）、<code>@container × @scope</code> 组合（组件样式完全自包含）。记住边界：style queries <strong>只查自定义属性</strong>，Firefox 尚未支持需渐进增强。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>style queries 只查自定义属性 --*；容器无需 container-type，默认即可查。</li><li>容器单位 cqi/cqw 按最近尺寸容器缩放；无容器时回退为视口单位。</li><li>嵌套容器必须命名：@container 名字 (条件)，否则查最近容器会串台。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 style queries 不需要给容器声明 <code>container-type</code>，而尺寸查询必须声明？</p><p><strong>答</strong>：尺寸查询需要容器建立独立的格式化上下文（<code>container-type: inline-size</code> 或 <code>size</code>），浏览器才能确定查询基准尺寸；style queries 只读取自定义属性的计算值，任何元素都有计算后的自定义属性，所以所有元素默认就是 style 查询容器（<code>container-type: normal</code> 的默认行为）。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>暗色侧栏 style queries + 容器单位排版 + 嵌套命名容器 + @container × @scope 组合：<a href="./../../examples/css/26-container-advanced/index-01-container-advanced.html">examples/css/26-container-advanced/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 42 话《Web Locks API》——多标签同时写 localStorage 数据互相覆盖？浏览器原生锁帮你排队：独占锁写、共享锁读、ifAvailable 不排队、AbortSignal 可超时。</p>',22)])])}const u=a(n,[["render",r]]);export{q as __pageData,u as default};
